@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/dm-mono/400.css";

/* Light (faithful): white page, ink #030712, sky #40cfff for every action (text on it stays
   near-black), seafoam #58dba6 as the second colour, mid grey #9b9b9b for quiet text,
   #eeeeee hairlines, #f7f7f7 icon tiles and placeholders, #f9fafb button hover. */
:root {
  --background: #ffffff;
  --foreground: #030712;
  --card: #ffffff;
  --card-foreground: #030712;
  --popover: #ffffff;
  --popover-foreground: #030712;
  --primary: #40cfff;
  --primary-foreground: #030712;
  --secondary: #f9fafb;
  --secondary-foreground: #030712;
  --muted: #f3f4f5;
  --muted-foreground: #9b9b9b;
  --accent: #eff5f8;
  --accent-foreground: #030712;
  --destructive: #b42318;
  --destructive-foreground: #ffffff;
  --border: #eeeeee;
  --input: rgb(0 0 0 / 10%);
  --ring: #40cfff;
  --highlight: #58dba6;
  --highlight-foreground: #030712;
  --glow: #40cfff;
  --chart-1: #40cfff;
  --chart-2: #58dba6;
  --chart-3: #009bcf;
  --chart-4: #a3e8ff;
  --chart-5: #4d4d4d;
  --sidebar: #f9fafb;
  --sidebar-foreground: #030712;
  --sidebar-primary: #40cfff;
  --sidebar-primary-foreground: #030712;
  --sidebar-accent: #eff5f8;
  --sidebar-accent-foreground: #030712;
  --sidebar-border: #eeeeee;
  --sidebar-ring: #40cfff;

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  --page-gutter: 1rem;
  --section-y: 5rem;
}

/* The original's gutters step up with the window: 16px on phones, 80px on desktop. */
@media (min-width: 48rem) {
  :root {
    --page-gutter: 2.5rem;
  }
}
@media (min-width: 64rem) {
  :root {
    --page-gutter: 5rem;
  }
}

/* Dark sibling: the original's own near-black (#030712) as the page, deep navy panels, the
   same sky and seafoam. */
.dark {
  --background: #030712;
  --foreground: #f9fafb;
  --card: #0b1220;
  --card-foreground: #f9fafb;
  --popover: #0b1220;
  --popover-foreground: #f9fafb;
  --primary: #40cfff;
  --primary-foreground: #030712;
  --secondary: #111827;
  --secondary-foreground: #f9fafb;
  --muted: #141b2a;
  --muted-foreground: #8b93a1;
  --accent: #10202c;
  --accent-foreground: #f9fafb;
  --destructive: #f0584c;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 10%);
  --input: rgb(255 255 255 / 16%);
  --ring: #40cfff;
  --highlight: #58dba6;
  --highlight-foreground: #030712;
  --glow: #009bcf;
  --chart-1: #40cfff;
  --chart-2: #58dba6;
  --chart-3: #009bcf;
  --chart-4: #a3e8ff;
  --chart-5: #c4c4c4;
  --sidebar: #0b1220;
  --sidebar-foreground: #f9fafb;
  --sidebar-primary: #40cfff;
  --sidebar-primary-foreground: #030712;
  --sidebar-accent: #141b2a;
  --sidebar-accent-foreground: #f9fafb;
  --sidebar-border: rgb(255 255 255 / 10%);
  --sidebar-ring: #40cfff;
}
